double limit(const std::string& n){if(n=="dc"||n=="dw"||n.rfind("dw",0)==0)return .03;if(n=="y"||n=="xhat"||n=="inverse"||n.find("selected")!=std::string::npos||n.find("_ds")!=std::string::npos)return .002;if(n=="dx"||n=="dg"||n=="db"||n=="residual"||n=="dln1")return .02;if(n.find("product")!=std::string::npos&&n.find("gate")==std::string::npos||n.find("_dot")!=std::string::npos&&n.find("gate")==std::string::npos||n.find("centered")!=std::string::npos)return .005;return .01;}
unsigned metric(const std::string& mode,unsigned index,const std::string& name,const one::Vec& ref,const one::Vec& host,const one::FV& actual,double gate){auto e=mmfixture::ln::errors(ref,actual);double r2=0,e2=0,mr=0,fp=0;for(unsigned j=0;j<ref.size();++j){double delta=actual[j]-ref[j];r2+=ref[j]*ref[j];e2+=delta*delta;mr=std::max(mr,std::fabs(delta)/std::max(.001,std::fabs(ref[j])));fp=std::max(fp,std::fabs(double(actual[j])-host[j]));}bool pass=!e.nonfinite&&e.absolute<=gate;
 std::printf("onemetric,%s,%u,%s,abs=%.12g,rms=%.12g,relative_l2=%.12g,max_relative=%.12g,fp_abs=%.12g,nonfinite=%zu,hash=%016llx,limit=%.12g,gate=%u\n",mode.c_str(),index,name.c_str(),e.absolute,e.rms,std::sqrt(e2/std::max(1e-300,r2)),mr,fp,e.nonfinite,(unsigned long long)hashWords(actual),gate,pass);return !pass;}
