  unsigned bad=metric("accumulation",batch,"dw",ref,one::d(fp),destination,.03);if(bad)std::exit(4);std::printf("oneaccum,%u,registry_index=%u,registry_offset=%zu,name=%s,role=MUON,rows=64,cols=64,microbatches=8,unique_inputs=8,scale=0.125,fp_word_mismatch=0,wall_with_shadow_validation_us=%.3f,updates=0\n",batch,target,offset,registry[target].name.c_str(),elapsed);
